//! Rust types of the vendored protobuf schema, generated by `build.rs`.
//!
//! The module is public so that the fake `fleet-telemetry` of the tests
//! (`examples/fake_fleet_telemetry.rs`) builds its payloads from the same
//! schema. The process itself uses the types only in the decode.
#![expect(
    clippy::doc_markdown,
    clippy::must_use_candidate,
    clippy::struct_excessive_bools,
    clippy::too_many_lines,
    reason = "prost-build generates this code from the upstream schema; it cannot follow the pedantic style"
)]

pub mod vehicle_data {
    include!(concat!(env!("OUT_DIR"), "/telemetry.vehicle_data.rs"));
}
pub mod vehicle_alerts {
    include!(concat!(env!("OUT_DIR"), "/telemetry.vehicle_alerts.rs"));
}
pub mod vehicle_error {
    include!(concat!(env!("OUT_DIR"), "/telemetry.vehicle_error.rs"));
}
pub mod vehicle_connectivity {
    include!(concat!(
        env!("OUT_DIR"),
        "/telemetry.vehicle_connectivity.rs"
    ));
}
